	@Test
	void compiledFeedbackAddsNoPostPrecompileAllocation() {
		final int warmupExecutions = 8_192;
		final int measuredExecutions = 4_096;
		QueryEvaluationStep[] baseline = precompiledAssignments(false, warmupExecutions + measuredExecutions);
		QueryEvaluationStep[] observed = precompiledAssignments(true, warmupExecutions + measuredExecutions);

		execute(baseline, 0, warmupExecutions);
		execute(observed, 0, warmupExecutions);

		com.sun.management.ThreadMXBean threadMxBean = (com.sun.management.ThreadMXBean) ManagementFactory
				.getThreadMXBean();
		assertThat(threadMxBean.isThreadAllocatedMemorySupported()).isTrue();
		boolean allocationTrackingEnabled = threadMxBean.isThreadAllocatedMemoryEnabled();
		try {
			if (!allocationTrackingEnabled) {
				threadMxBean.setThreadAllocatedMemoryEnabled(true);
			}
			long baselineBytes = allocatedBytes(threadMxBean, baseline, warmupExecutions, measuredExecutions);
			long observedBytes = allocatedBytes(threadMxBean, observed, warmupExecutions, measuredExecutions);

			assertThat(observedBytes)
					.as("ordinary learned feedback must add no allocation after precompile; baseline=%s, observed=%s",
							baselineBytes, observedBytes)
					.isLessThanOrEqualTo(baselineBytes);
		} finally {
			if (!allocationTrackingEnabled) {
				threadMxBean.setThreadAllocatedMemoryEnabled(false);
			}
		}
	}

	private static QueryEvaluationStep[] precompiledAssignments(boolean feedbackEnabled, int count) {
		GuardedBindingSetAssignment assignment = trackedAssignment();
		if (!feedbackEnabled) {
			assignment.setRuntimeFeedbackContract(null);
			assignment.setCostFeedbackTrackingEnabled(false);
		}
		RecordingEvaluationStatistics statistics = new RecordingEvaluationStatistics();
		DefaultEvaluationStrategy strategy = new DefaultEvaluationStrategy(new EmptyTripleSource(), null, null, 0,
				statistics);
		QueryEvaluationStep[] compiled = new QueryEvaluationStep[count];
		for (int index = 0; index < compiled.length; index++) {
			compiled[index] = strategy.precompile(new QueryRoot(assignment));
		}
		return compiled;
	}

	private static long allocatedBytes(com.sun.management.ThreadMXBean threadMxBean,
			QueryEvaluationStep[] compiled, int offset, int count) {
		long threadId = Thread.currentThread().threadId();
		long counterBefore = threadMxBean.getThreadAllocatedBytes(threadId);
		long counterAfter = threadMxBean.getThreadAllocatedBytes(threadId);
		long counterReadBytes = counterAfter - counterBefore;
		long before = threadMxBean.getThreadAllocatedBytes(threadId);
		execute(compiled, offset, count);
		return threadMxBean.getThreadAllocatedBytes(threadId) - before - counterReadBytes;
	}

	private static void execute(QueryEvaluationStep[] compiled, int offset, int count) {
		for (int index = offset; index < offset + count; index++) {
			try (CloseableIteration<BindingSet> results = compiled[index].evaluate(EmptyBindingSet.getInstance())) {
				while (results.hasNext()) {
					results.next();
				}
			}
		}
	}

	private static void assertAbortedRootPublication(RuntimeException failure, boolean cancelled) {
		GuardedBindingSetAssignment assignment = trackedAssignment();
		RecordingEvaluationStatistics statistics = new RecordingEvaluationStatistics();
		DefaultEvaluationStrategy strategy = failAfterFirstRowStrategy(statistics, failure);
		QueryEvaluationStep compiled = strategy.precompile(new QueryRoot(assignment));

		try (CloseableIteration<BindingSet> results = compiled.evaluate(EmptyBindingSet.getInstance())) {
			assertThat(results.hasNext()).isTrue();
			results.next();
			org.assertj.core.api.Assertions.assertThatThrownBy(results::hasNext)
					.isSameAs(failure);
		}

		assertThat(statistics.recordCalls).isEqualTo(1L);
		assertThat(statistics.lastObservation.rootCompleted()).isFalse();
		assertThat(statistics.lastObservation.cancellations()).isEqualTo(cancelled ? 1L : 0L);
		assertThat(statistics.lastObservation.failures()).isEqualTo(cancelled ? 0L : 1L);
		assertThat(statistics.lastObservation.exhaustedOpens()).isZero();
	}

	private static DefaultEvaluationStrategy failAfterFirstRowStrategy(RecordingEvaluationStatistics statistics,
			RuntimeException failure) {
		return new DefaultEvaluationStrategy(new EmptyTripleSource(), null, null, 0, statistics) {
			@Override
			protected QueryEvaluationStep prepare(BindingSetAssignment node, QueryEvaluationContext context) {
				return bindings -> new CloseableIteration<>() {
					private final java.util.Iterator<BindingSet> rows = node.getBindingSets().iterator();
					private boolean served;

					@Override
					public boolean hasNext() {
						if (served) {
							throw failure;
						}
						return rows.hasNext();
					}

					@Override
					public BindingSet next() {
						served = true;
						return rows.next();
					}

					@Override
					public void remove() {
						throw new UnsupportedOperationException();
					}

					@Override
					public void close() {
					}
				};
			}
		};
	}

	private static GuardedBindingSetAssignment trackedAssignment() {
		QueryBindingSet row = new QueryBindingSet();
		row.addBinding("value", SimpleValueFactory.getInstance().createLiteral("row"));
		GuardedBindingSetAssignment assignment = new GuardedBindingSetAssignment();
		assignment.setBindingSets(List.of(row));
		assignment.setCostFeedbackTrackingEnabled(true);
		assignment.setCostFeedbackExpectedRows(1.0d);
		assignment.setCostFeedbackExpectedWorkRows(1.0d);
		assignment.setRuntimeFeedbackContract(contract(1.0d));
		return assignment;
	}

	private static RuntimeFeedbackContract contract(double rows) {
		RuntimeFeedbackContract.PredictionVector prediction = prediction(rows);
		return new RuntimeFeedbackContract(new TestDescriptor(), prediction, prediction, rows, rows, rows,
				Double.POSITIVE_INFINITY, RuntimeFeedbackContract.SemanticKind.ORDINARY,
				RuntimeFeedbackContract.Algorithm.SCAN, RuntimeFeedbackContract.Access.NONE, 1, 0L, 0L, 0L,
				RuntimeFeedbackContract.ADMIT_LOGICAL | RuntimeFeedbackContract.ADMIT_PHYSICAL);
	}

	private static RuntimeFeedbackContract.PredictionVector prediction(double rows) {
		return new RuntimeFeedbackContract.PredictionVector(rows, rows, rows, Double.NaN, Double.NaN, 1.0d,
				Double.NaN, Double.NaN, Double.NaN, Double.NaN, Double.NaN, Double.NaN);
	}

	private static final class RecordingEvaluationStatistics extends EvaluationStatistics {
		private long resolveCalls;
		private long recordCalls;
		private InvocationAggregateView lastObservation;

		@Override
		public RuntimeFeedbackTarget resolveRuntimeFeedbackTarget(QueryModelNode node,
				RuntimeFeedbackContract contract) {
			resolveCalls++;
			return super.resolveRuntimeFeedbackTarget(node, contract);
		}

		@Override
		public void recordOperatorOutcome(QueryModelNode node, InvocationAggregateView observation) {
			recordCalls++;
			lastObservation = observation;
		}
	}

